<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../layouts/AdminLayout.vue';
type Report = { entity: string; id: string; label: string; allowed: boolean; reasons: string[]; counts: Record<string, number>; retained: string[] };
defineProps<{ demoEnabled?: boolean; demoCounts?: Record<string, number>; preview: Report | null; counts: Record<string, number>; badges: Record<string, number>; durations: Record<string, number>; approved: boolean; events: { id: string; name: string; status: string | null }[]; history: { id: number; actor_id: string | null; occurred_at: string; action: string; details: string }[]; requests: { id: string; operation: string; status: string; result: unknown; created_at: string }[]; pendingFiles: number; maintenanceReport: { operation: string; counts?: Record<string, number>; events?: { id: string; personnes: number; photos_echues: boolean; historique_echu: boolean; photos: number; mouvements: number; notifications: number; alertes: number }[]; retained?: string[] } | null }>();
const deletion = useForm({ reference: '', password: '' });
const analyse = useForm({ operation: 'demo' });
const maintenance = useForm({ operation: '', confirmation: '', password: '' });
function remove() { deletion.post('/administration/donnees/supprimer', { onFinish: () => deletion.reset('password') }); }
function request(operation: string) { maintenance.operation = operation; maintenance.post('/administration/donnees/demander', { onFinish: () => maintenance.reset('password') }); }
const labels: Record<string, string> = { badge: 'Badge', visitors: 'Fiches de personnes', badges: 'Badges', events: 'Événements', categories: 'Catégories', zones: 'Zones', category_zone: 'Autorisations de zones', groups: 'Groupes', badge_batches: 'Lots', visiteurs: 'Personnes', evenements: 'Événements', comptes_fictifs: 'Comptes fictifs', synchronisations: 'Synchronisations', photos: 'Photos', notifications: 'Notifications', alertes: 'Alertes', audit: 'Journal d’audit', evenements_ouverts: 'Événements ouverts', evenements_clos: 'Événements clôturés', evenements_archives: 'Événements archivés', personnes_actives: 'Personnes actives', personnes_retirees: 'Personnes retirées', en_attente: 'En attente du service de maintenance', base_validee: 'Données traitées, fichiers à vérifier', fichiers_a_reprendre: 'Effacement de fichiers à reprendre', terminee: 'Terminée', refusee: 'Refusée' };
const operationNames: Record<string, string> = { 'gestion.maintenance_terminee': 'Nettoyage terminé', 'gestion.fichiers_a_reprendre': 'Effacement de fichiers à reprendre', 'gestion.suppression': 'Suppression effectuée', 'gestion.suppression_refusee': 'Suppression refusée', 'gestion.transition_refusee': 'Clôture ou archivage refusé', 'gestion.cloturer': 'Événement clôturé', 'gestion.archiver': 'Événement archivé', 'gestion.retrait_refuse': 'Retrait refusé', 'gestion.evenement_modifie': 'Événement modifié', 'gestion.maintenance_demandee': 'Nettoyage demandé', 'gestion.maintenance_base_validee': 'Données traitées, vérification des fichiers', 'gestion.maintenance_refusee': 'Nettoyage refusé', 'gestion.analyse_refusee': 'Analyse refusée', 'gestion.demande_refusee': 'Demande refusée', 'donnees.purgees': 'Conservation appliquée', 'demo.donnees_purgees': 'Démonstration nettoyée' };
</script>
<template>
  <AdminLayout active="donnees">
    <h1 class="text-display font-bold">Gestion des données</h1>
    <p class="admin-muted my-4">Retrouvez les archives et préparez les nettoyages admissibles. Les historiques protégés restent conservés.</p><div v-if="demoEnabled" class="admin-card my-4"><h2>Vous cherchez à générer ou remettre à zéro des données de test ?</h2><p class="my-3">Ce menu concerne la conservation. Pour créer des invités fictifs ou repartir d’une installation métier vide, utilisez le laboratoire.</p><Link class="btn-soft" href="/administration/demonstration">Ouvrir Démonstration et remise à zéro</Link></div>
    <div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><section v-for="(total, key) in counts" :key="key" class="admin-card"><h2>{{ labels[key] }}</h2><p class="text-3xl font-bold">{{ total }}</p></section></div>
    <section class="admin-card my-5"><h2>Badges par état</h2><dl class="mt-4 flex flex-wrap gap-6"><div v-for="(total, status) in badges" :key="status"><dt>{{ status }}</dt><dd class="font-bold">{{ total }}</dd></div></dl></section>
    <section v-if="preview" class="admin-card my-5" aria-labelledby="analyse-title">
      <h2 id="analyse-title">Analyse avant suppression · {{ preview.label }}</h2>
      <p class="my-3">Référence : <strong class="break-all">{{ preview.id }}</strong></p>
      <p>Suppression définitive et irréversible. Aperçu valable dix minutes ; toute modification des données impose une nouvelle analyse.</p>
      <dl class="my-4"><div v-for="(total, type) in preview.counts" :key="type" class="flex gap-3"><dt>{{ labels[type] ?? type }}</dt><dd>{{ total }}</dd></div></dl>
      <p v-for="reason in preview.reasons" :key="reason" role="alert" class="my-3 font-semibold text-red-800">{{ reason }}</p>
      <p v-for="item in preview.retained" :key="item">Conservé : {{ item }}</p>
      <form v-if="preview.allowed" class="mt-5 space-y-4" @submit.prevent="remove"><label class="block">Recopiez la référence ci-dessus<input v-model="deletion.reference" class="field" required autocomplete="off"></label><label class="block">Confirmez votre mot de passe<input v-model="deletion.password" class="field" type="password" required autocomplete="current-password"></label><p v-for="error in deletion.errors" :key="error" role="alert" class="text-red-800">{{ error }}</p><button class="btn-soft border-red-700 text-red-800" :disabled="deletion.processing">Confirmer la suppression définitive</button></form>
    </section>
    <section class="admin-card my-5"><h2>Archives</h2><p class="my-3">Les événements archivés restent consultables ; ils n’acceptent plus de nouvelles admissions.</p><Link class="btn-soft" href="/administration/evenements?archives=1">Consulter les événements archivés</Link></section>
    <section class="admin-card my-5"><h2>Conservation et anonymisation</h2><p class="my-3">Politique {{ approved ? 'approuvée' : 'en attente d’approbation' }}. L’anonymisation intervient à échéance et conserve les références statistiques.</p><dl><div v-for="(days, type) in durations" :key="type" class="flex gap-3"><dt>{{ labels[type] ?? type }}</dt><dd>{{ days }} jours</dd></div></dl><Link class="btn-soft mt-4" href="/administration/conservation">Consulter la politique</Link></section>
    <section class="admin-card my-5"><h2>Préparer un nettoyage</h2><p v-for="(total, type) in demoCounts" :key="type">Jeu de démonstration identifié · {{ labels[type] ?? type }} : {{ total }}</p><p class="my-3">La démonstration utilise uniquement le jeu fictif identifié. Les données réelles suivent la politique de conservation. Une sauvegarde de la base et des fichiers sera vérifiée par le service de maintenance.</p><form class="space-y-4" @submit.prevent="analyse.post('/administration/donnees/analyser')"><label class="block">Opération<select v-model="analyse.operation" class="field"><option value="demo">Nettoyer le jeu de démonstration</option><option value="conservation">Appliquer la conservation et anonymiser à échéance</option></select></label><p v-for="error in analyse.errors" :key="error" role="alert" class="text-red-800">{{ error }}</p><button class="btn-soft" :disabled="analyse.processing">Analyser sans supprimer</button></form>
      <div v-if="maintenanceReport" class="mt-5 space-y-3"><h3 class="font-bold">Rapport · {{ maintenanceReport.operation === 'demo' ? 'Démonstration' : 'Conservation' }}</h3><p>Cette opération est irréversible. Le journal d’audit est conservé.</p><p v-for="(total, type) in maintenanceReport.counts" :key="type">{{ labels[type] ?? type }} : {{ total }}</p><ul><li v-for="event in maintenanceReport.events" :key="event.id" class="my-3 break-all">Événement {{ event.id }} : {{ event.personnes }} identité(s) à anonymiser, {{ event.photos }} photo(s), {{ event.mouvements }} mouvement(s), {{ event.notifications }} notification(s) et {{ event.alertes }} alerte(s) résolue(s) à effacer. Les autres données restent conservées.</li></ul><p v-for="item in maintenanceReport.retained" :key="item">{{ item }}</p><form class="space-y-4" @submit.prevent="request(maintenanceReport.operation)"><label class="block">Pour confirmer, écrivez « {{ maintenanceReport.operation }} »<input v-model="maintenance.confirmation" class="field" required autocomplete="off"></label><label class="block">Votre mot de passe<input v-model="maintenance.password" class="field" type="password" required autocomplete="current-password"></label><p v-for="error in maintenance.errors" :key="error" role="alert" class="text-red-800">{{ error }}</p><button class="btn-soft" :disabled="maintenance.processing">Demander l’exécution sécurisée</button></form></div>
    </section>
    <section class="admin-card my-5"><h2>Demandes de nettoyage</h2><p class="my-3">{{ pendingFiles }} fichier(s) en attente d’effacement. Une demande en attente n’est pas une opération terminée.</p><p v-if="!requests.length">Aucune demande enregistrée.</p><ul><li v-for="item in requests" :key="item.id" class="my-4 border-b pb-4"><strong>{{ item.operation === 'demo' ? 'Démonstration' : 'Conservation' }} · {{ labels[item.status] ?? item.status }}</strong><p class="break-all">Référence {{ item.id }} · {{ item.created_at }}</p><pre v-if="item.result" class="mt-2 whitespace-pre-wrap break-words">{{ typeof item.result === 'string' ? JSON.parse(item.result) : item.result }}</pre></li></ul></section>
    <section class="admin-card my-5"><h2>Historique des opérations</h2><p v-if="!history.length" class="my-3">Aucune opération de gestion enregistrée.</p><ul><li v-for="item in history" :key="item.id" class="my-3 border-b pb-3"><strong>{{ operationNames[item.action] ?? 'Opération de gestion' }}</strong><p class="break-all">{{ item.occurred_at }} · Auteur : {{ item.actor_id ?? 'Maintenance' }}</p></li></ul></section>
  </AdminLayout>
</template>
